const CITY_TO_DEPARTMENT: Record<string, string> = {
  meynes: '30', nimes: '30', 'nîmes': '30', uzes: '30', 'uzès': '30', remoulins: '30', collias: '30',
  carpentras: '84', avignon: '84', orange: '84',
  marseille: '13', marignane: '13', 'aix-en-provence': '13', aix: '13',
  valence: '26', romans: '26', 'romans-sur-isere': '26', 'romans-sur-isère': '26',
  paris: '75', courbevoie: '92', nanterre: '92',
  montpellier: '34', beziers: '34', 'béziers': '34',
  lyon: '69', grenoble: '38', nice: '06', toulon: '83',
  toulouse: '31', bordeaux: '33', biarritz: '64',
  lille: '59', strasbourg: '67', nantes: '44', rennes: '35', rouen: '76',
};

function normalize(value: string) {
  return value
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLocaleLowerCase('fr')
    .replace(/[’']/g, '-')
    .replace(/\s+/g, ' ')
    .trim();
}

function departmentFromLocation(location: string): DepartmentInfo | null {
  if (!location.trim()) return null;

  const upper = location.toLocaleUpperCase('fr');
  const explicit = upper.match(/(?:\(|\b)(2A|2B|0[1-9]|[1-8][0-9]|9[0-5])(?:\)|\b)/)?.[1];
  if (explicit) {
    const found = DEPARTMENTS.find((department) => department.code === explicit);
    if (found) return found;
  }

  const postal = upper.match(/\b(0[1-9]|[1-8][0-9]|9[0-5])\d{3}\b/)?.[1];
  if (postal) {
    const found = DEPARTMENTS.find((department) => department.code === postal);
    if (found) return found;
  }

  const normalized = normalize(location);
  for (const department of DEPARTMENTS) {
    if (normalized.includes(normalize(department.name))) return department;
  }

  for (const [city, code] of Object.entries(CITY_TO_DEPARTMENT)) {
    if (normalized.includes(normalize(city))) {
      return DEPARTMENTS.find((department) => department.code === code) ?? null;
    }
  }

  return null;
}

function zoneLabel(zone: ZoneId) {
  const config = ZONES.find((entry) => entry.id === zone);
  return config ? t(config.labelKey) : '';
}

export default function ExploreScreen() {
  const { session } = useAuth();
  const userId = session?.user.id ?? '';

  const [members, setMembers] = useState<MemberDirectoryEntry[]>([]);
  const [onlineIds, setOnlineIds] = useState<Set<string>>(() => new Set());
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [selectedMember, setSelectedMember] = useState<MemberDirectoryEntry | null>(null);
  const [selectedZone, setSelectedZone] = useState<ZoneId | null>(null);
  const [selectedDepartment, setSelectedDepartment] = useState<string | null>(null);

  const loadMembers = useCallback(async () => {
    setError(null);

    if (!userId) {
      setMembers([]);
      setOnlineIds(new Set());
      setLoading(false);
      setRefreshing(false);
      return;
    }

    try {
      const presenceCutoff = new Date(Date.now() - 90000).toISOString();
      const [result, presenceResult] = await Promise.all([
        listMembers(true),
        getSupabase()
          .from('user_presence')
          .select('user_id')
          .gte('updated_at', presenceCutoff),
      ]);

      setMembers(result);
      if (!presenceResult.error) {
        setOnlineIds(new Set((presenceResult.data ?? []).map((row) => String(row.user_id))));
      }
    } catch {
      setError(t('communityLoadError'));
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  }, [userId]);

  useFocusEffect(
    useCallback(() => {
      void loadMembers();
      const timer = setInterval(() => {
        if (AppState.currentState === 'active') void loadMembers();
      }, 15000);
      const listener = AppState.addEventListener('change', (state) => {
        if (state === 'active') void loadMembers();
      });
      return () => {
        clearInterval(timer);
        listener.remove();
      };
    }, [loadMembers])
  );

  const refresh = () => {
    setRefreshing(true);
    void loadMembers();
  };

  const locatedMembers = useMemo<LocatedMember[]>(() => members.map((member) => ({
    ...member,
    department: departmentFromLocation(member.location),
  })), [members]);

  const zoneStats = useMemo(() => ZONES.map((zone) => {
    const people = locatedMembers.filter((member) => member.department?.zone === zone.id);
    return {
      ...zone,
      total: people.length,
      online: people.filter((member) => onlineIds.has(member.userId)).length,
    };
  }), [locatedMembers, onlineIds]);

  const departmentStats = useMemo(() => {
    if (!selectedZone) return [];
    const grouped = new Map<string, { department: DepartmentInfo; total: number; online: number }>();

    for (const member of locatedMembers) {
      const department = member.department;
      if (!department || department.zone !== selectedZone) continue;
      const current = grouped.get(department.code) ?? { department, total: 0, online: 0 };
      current.total += 1;
      if (onlineIds.has(member.userId)) current.online += 1;
      grouped.set(department.code, current);
    }

    return Array.from(grouped.values()).sort((a, b) =>
      b.online - a.online || b.total - a.total || a.department.name.localeCompare(b.department.name, 'fr'));
  }, [locatedMembers, onlineIds, selectedZone]);

  const visibleMembers = useMemo(() => {
    if (selectedDepartment) {
      return locatedMembers.filter((member) => member.department?.code === selectedDepartment);
    }
    if (selectedZone) {
      return locatedMembers.filter((member) => member.department?.zone === selectedZone);
    }
    return locatedMembers;
  }, [locatedMembers, selectedDepartment, selectedZone]);

  const selectedDepartmentInfo = useMemo(() =>
    selectedDepartment ? DEPARTMENTS.find((department) => department.code === selectedDepartment) ?? null : null,
  [selectedDepartment]);

  const wheelNames = useMemo(() => {
    if (!selectedMember) return [];
    return Object.values(selectedMember.wheels ?? {})
      .map((wheel) => wheel?.name?.trim())
      .filter((name): name is string => Boolean(name));
  }, [selectedMember]);

  const chooseZone = (zone: ZoneId) => {
    setSelectedZone(zone);
    setSelectedDepartment(null);
  };

  const backToFrance = () => {
    setSelectedZone(null);
    setSelectedDepartment(null);
  };

  return (
    <>
      <SafeAreaView style={styles.safeArea}>
        <ScrollView
          contentContainerStyle={styles.container}
          refreshControl={<RefreshControl refreshing={refreshing} onRefresh={refresh} />}
        >
          <ScreenBackButton />

          <View style={styles.header}>
            <View style={styles.headerText}>
              <Text style={styles.title}>{t('communityTitle')}</Text>
              <Text style={styles.subtitle}>{t('communitySubtitle')}</Text>
            </View>

            <Pressable
              style={styles.refreshButton}
              accessibilityRole="button"
              accessibilityLabel={t('refreshMembers')}
              onPress={refresh}
            >
              <Ionicons name="refresh" size={24} color={ACTION_CYAN} />
            </Pressable>
          </View>

          {!userId ? (
            <View style={styles.emptyCard}>
              <Text style={styles.emptyTitle}>{t('communitySignInTitle')}</Text>
              <Text style={styles.emptyText}>{t('communitySignInText')}</Text>
            </View>
          ) : loading ? (
            <View style={styles.emptyCard}>
              <Text style={styles.emptyTitle}>{t('loading')}</Text>
              <Text style={styles.emptyText}>{t('communityLoadingText')}</Text>
            </View>
          ) : error ? (
            <View style={styles.emptyCard}>
              <Text style={styles.emptyTitle}>{t('connectionFailed')}</Text>
              <Text style={styles.emptyText}>{error}</Text>
              <Pressable style={styles.retryButton} onPress={refresh}>
                <Text style={styles.retryText}>{t('retry')}</Text>
              </Pressable>
            </View>
          ) : members.length === 0 ? (
            <View style={styles.emptyCard}>
              <Text style={styles.emptyTitle}>{t('noOtherWheeler')}</Text>
              <Text style={styles.emptyText}>{t('newMembersAppearHere')}</Text>
            </View>
          ) : (
            <>
              <View style={styles.mapCard}>
                <View style={styles.mapTitleRow}>
                  <View style={styles.mapTitleText}>
                    <Text style={styles.sectionTitle}>{t('communityMapTitle')}</Text>
                    <Text style={styles.mapSubtitle}>{t('communityMapSubtitle')}</Text>
                  </View>
                  <Ionicons name="map" size={28} color={ACTION_CYAN} />
                </View>

                {!selectedZone ? (
                  <View style={styles.franceMap}>
                    <Image source={FRANCE_MAP_IMAGE} style={styles.franceMapImage} resizeMode="cover" />
                    {zoneStats.map((zone) => (
                      <FranceZoneMarker
                        key={zone.id}
                        zone={zone}
                        onPress={() => chooseZone(zone.id)}
                      />
                    ))}
                  </View>
                ) : (
                  <View>
                    <Pressable style={styles.mapBackButton} onPress={backToFrance}>
                      <Ionicons name="chevron-back" size={18} color={ACTION_CYAN} />
                      <Text style={styles.mapBackText}>{t('mapBackFrance')}</Text>
                    </Pressable>

                    <View style={styles.selectedZoneHeader}>
                      <Text style={styles.selectedZoneTitle}>{zoneLabel(selectedZone)}</Text>
                      <Text style={styles.selectedZoneMeta}>
                        {zoneStats.find((zone) => zone.id === selectedZone)?.online ?? 0} {t('mapOnlineNow')} · {zoneStats.find((zone) => zone.id === selectedZone)?.total ?? 0} {t('mapMembers')}
                      </Text>
                    </View>

                    <Text style={styles.departmentHeading}>{t('mapDepartments')}</Text>
                    {departmentStats.length === 0 ? (
                      <Text style={styles.mapEmpty}>{t('mapNoDepartment')}</Text>
                    ) : (
                      <View style={styles.departmentGrid}>
                        {departmentStats.map(({ department, total, online }) => {
                          const selected = selectedDepartment === department.code;
                          return (
                            <Pressable
                              key={department.code}
                              style={[styles.departmentButton, selected && styles.departmentButtonSelected]}
                              onPress={() => setSelectedDepartment(department.code)}
                            >
                              <View style={styles.departmentTopLine}>
                                <Text style={styles.departmentCode}>{department.code}</Text>
                                <View style={styles.onlineBadgeSmall}>
                                  <View style={styles.onlineDot} />
                                  <Text style={styles.onlineBadgeText}>{online}</Text>
                                </View>
                              </View>
                              <Text style={styles.departmentName} numberOfLines={2}>{department.name}</Text>
                              <Text style={styles.departmentTotal}>{total} {t('mapMembers')}</Text>
                            </Pressable>
                          );
                        })}
                      </View>
                    )}
                  </View>
                )}

                <View style={styles.privacyRow}>
                  <Ionicons name="shield-checkmark" size={17} color={wcTheme.colors.green} />
                  <Text style={styles.privacyText}>{t('mapLocationHint')}</Text>
                </View>
              </View>

              <Text style={styles.sectionTitle}>
                {selectedDepartmentInfo ? `${t('mapDepartmentMembers')} · ${selectedDepartmentInfo.name}` : t('members')}
              </Text>

              {visibleMembers.map((member) => {
                const online = onlineIds.has(member.userId);
                return (
                  <Pressable
                    key={member.userId}
                    style={({ pressed }) => [styles.card, pressed && styles.cardPressed]}
                    accessibilityRole="button"
                    accessibilityLabel={`Voir ${member.displayName || t('thisWheeler')}`}
                    onPress={() => setSelectedMember(member)}
                  >
                    <View style={styles.avatarWrap}>
                      <View style={styles.avatar}>
                        {member.avatarUrl ? (
                          <Image source={{ uri: member.avatarUrl }} style={styles.avatarImage} />
                        ) : (
                          <Ionicons name="person" size={28} color="#0b1c24" />
                        )}
                      </View>
                      {online ? <View style={styles.avatarOnlineDot} /> : null}
                    </View>

                    <View style={styles.cardContent}>
                      <View style={styles.memberNameRow}>
                        <Text style={styles.name}>{member.displayName || t('wheeler')}</Text>
                        {online ? <Text style={styles.onlineText}>● {t('mapOnlineNow')}</Text> : null}
                      </View>
                      {!!member.username && <Text style={styles.username}>@{member.username}</Text>}
                      <Text style={styles.info}>{member.location || t('locationUnknown')}</Text>
                    </View>

                    <Ionicons name="chevron-forward" size={24} color="#7e8b93" />
                  </Pressable>
                );
              })}
            </>
          )}

          <Pressable style={styles.gpsCard} onPress={() => router.push('/parcours-gps')}>
            <View style={styles.gpsIcon}>
              <Ionicons name="navigate" size={28} color="#071a23" />
            </View>

            <View style={styles.gpsContent}>
              <Text style={styles.gpsTitle}>Enregistrer un parcours</Text>
              <Text style={styles.gpsText}>
                Démarrer, mettre en pause et sauvegarder votre balade avec le GPS du téléphone.
              </Text>
            </View>

            <Ionicons name="chevron-forward" size={24} color={ACTION_CYAN} />
          </Pressable>
        </ScrollView>
      </SafeAreaView>

      <Modal
        visible={selectedMember !== null}
        transparent
        animationType="fade"
        onRequestClose={() => setSelectedMember(null)}
      >
        <View style={styles.modalBackdrop}>
          <View style={styles.memberModal}>
            {selectedMember && (
              <>
                <View style={styles.modalAvatarWrap}>
                  {selectedMember.avatarUrl ? (
                    <Image
                      source={{ uri: selectedMember.avatarUrl }}
                      style={styles.modalAvatarImage}
                    />
                  ) : (
                    <View style={styles.modalAvatarFallback}>
                      <Ionicons name="person" size={42} color="#0b1c24" />
                    </View>
                  )}
                </View>

                <Text style={styles.modalName}>
                  {selectedMember.displayName || t('wheeler')}
                </Text>

                {!!selectedMember.username && (
                  <Text style={styles.modalUsername}>@{selectedMember.username}</Text>
                )}

                <Text style={styles.modalInfo}>
                  {selectedMember.location || t('locationUnknown')}
                </Text>

                <View style={styles.modalStats}>
                  {!!selectedMember.age && (
                    <View style={styles.modalStat}>
                      <Text style={styles.modalStatValue}>{selectedMember.age}</Text>
                      <Text style={styles.modalStatLabel}>ans</Text>
                    </View>
                  )}

                  {!!selectedMember.practiceYears && (
                    <View style={styles.modalStat}>
                      <Text style={styles.modalStatValue}>{selectedMember.practiceYears}</Text>
                      <Text style={styles.modalStatLabel}>
                        an{selectedMember.practiceYears === '1' ? '' : 's'} de pratique
                      </Text>
                    </View>
                  )}

                  {!!selectedMember.level && (
                    <View style={styles.modalStat}>
                      <Text style={styles.modalStatValue}>{selectedMember.level}</Text>
                      <Text style={styles.modalStatLabel}>niveau</Text>
                    </View>
                  )}
                </View>

                {!!selectedMember.bio && (
                  <Text style={styles.modalBio}>{selectedMember.bio}</Text>
                )}

                {wheelNames.length > 0 && (
                  <Text style={styles.modalWheels}>
                    Roue{wheelNames.length > 1 ? 's' : ''} : {wheelNames.join(' · ')}
                  </Text>
                )}

                <Text style={styles.modalContact}>
                  Vous pouvez contacter ce membre depuis l'onglet Messages.
                </Text>

                <Pressable
                  style={styles.closeModalButton}
                  accessibilityRole="button"
                  accessibilityLabel="Fermer"
                  onPress={() => setSelectedMember(null)}
                >
                  <Text style={styles.closeModalText}>Fermer</Text>
                </Pressable>
              </>
            )}
          </View>
        </View>
      </Modal>
    </>
  );
}

function FranceZoneMarker({ zone, onPress }: {
  zone: { id: ZoneId; labelKey: 'zoneNorthWest' | 'zoneNorthEast' | 'zoneIleDeFrance' | 'zoneCenterWest' | 'zoneSouthWest' | 'zoneSouthEast'; total: number; online: number };
  onPress: () => void;
}) {
  const positions: Record<ZoneId, { top: `${number}%`; left: `${number}%` }> = {
    northWest: { top: '18%', left: '37%' },
    northEast: { top: '20%', left: '74%' },
    ileDeFrance: { top: '34%', left: '55%' },
    centerWest: { top: '43%', left: '36%' },
    southWest: { top: '65%', left: '35%' },
    southEast: { top: '61%', left: '70%' },
  };

  return (
    <Pressable
      accessibilityRole="button"
      accessibilityLabel={`${t(zone.labelKey)} · ${zone.online} ${t('mapOnlineNow')} · ${zone.total} ${t('mapMembers')}`}
      style={[styles.franceZoneMarker, positions[zone.id]]}
      onPress={onPress}
      hitSlop={12}
    >
      <Text style={[styles.franceZoneCount, zone.online > 0 && styles.franceZoneCountActive]}>{zone.online}</Text>
      <Text style={styles.franceZoneLabel} numberOfLines={2}>{t(zone.labelKey)}</Text>
    </Pressable>
  );
}

